// Program.cs - one-time setup
builder.Services.AddOpenTelemetry()
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation()   // incoming requests
        .AddHttpClientInstrumentation()   // outgoing HttpClient calls
        .AddEntityFrameworkCoreInstrumentation()
        .AddSource("Orders.Workers")
        .UseOtlpExporter());

// Manual span around domain work
using var activity = OrdersDiagnostics.ActivitySource.StartActivity("PlaceOrder");
activity?.SetTag("order.id", orderId);
activity?.SetTag("order.item_count", items.Count);

// Producer side: context flows through message headers automatically
// (OpenTelemetry messaging instrumentation injects traceparent)
await bus.PublishAsync(new OrderPlaced(orderId), ct);

// Consumer side: extract parent context, start child span
var consumerActivity = OrdersDiagnostics.ActivitySource
    .StartActivity("OrderPlaced.Handle", ActivityKind.Consumer);
// span is a child of the producer's span -> one trace across the queue

// Logs stitched to the same trace (Serilog):
// Log.ForContext("OrderId", orderId).Information("Reserved stock");
// -> log entry carries TraceId/SpanId; clicking a span shows its logs

// Reading it in the backend (Jaeger/Tempo/Azure):
// trace waterfall: POST /orders [410ms]
//   |- PlaceOrder [390ms]
//   |   |- EF: SELECT Products [12ms]
//   |   |- HTTP payments.charge [350ms]  <- the bottleneck, visible immediately
//   |   '- bus.publish OrderPlaced [3ms]
